{
  "name": "opencode-probity",
  "version": "0.3.0",
  "description": "OpenCode plugin that enforces TDD workflow using probity",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "probity",
    "tdd",
    "test-driven-development"
  ],
  "license": "MIT",
  "author": {
    "name": "Anthony Roy",
    "email": "aroy@dius.com.au"
  },
  "type": "module",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    }
  },
  "repository": {
    "type": "git",
    "url": "https://github.com/anthony-dius/opencode-probity"
  },
  "homepage": "https://github.com/anthony-dius/opencode-probity#readme",
  "bugs": {
    "url": "https://github.com/anthony-dius/opencode-probity/issues"
  },
  "publishConfig": {
    "access": "public",
